#!/usr/bin/env python3
"""Build the public portal from the same guide content embedded in the app."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];SITE=ROOT/'site'
H=lambda s:html.escape(str(s),quote=True)
REPO='https://github.com/infinialabs-ai/xailon-hub-releases'
DOMAIN='https://xailonhub.infinialabs.ai'
guides=json.loads((SITE/'assets/help/guide.json').read_text())
release=json.loads((ROOT/'release.json').read_text())
icons={'mac':'<path d="M16 3c-2 0-3 2-3 4 2 0 3-2 3-4Z"/><path d="M19 16c-1 3-2 5-4 5-1 0-2-1-3-1s-2 1-3 1c-2 0-5-5-5-9 0-3 2-5 4-5 2 0 3 1 4 1s3-1 4-1c2 0 3 1 4 2-4 2-3 6-1 7Z"/>','windows':'<path d="m3 5 8-1v7H3Zm10-1 8-1v8h-8ZM3 13h8v7l-8-1Zm10 0h8v8l-8-1Z"/>','linux':'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4m-5-9 2 2-2 2m5 0h3"/>','laptop':'<rect x="4" y="3" width="16" height="13" rx="2"/><path d="m4 16-3 4h22l-3-4M9 20h6"/>','hub':'<circle cx="12" cy="12" r="3"/><circle cx="4" cy="4" r="2"/><circle cx="20" cy="4" r="2"/><circle cx="4" cy="20" r="2"/><circle cx="20" cy="20" r="2"/><path d="m6 6 4 4m4 4 4 4M6 18l4-4m4-4 4-4"/>','chat':'<path d="M20 16a3 3 0 0 1-3 3H9l-5 3V6a3 3 0 0 1 3-3h10a3 3 0 0 1 3 3Z"/><path d="M8 8h8m-8 4h5"/>','shield':'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>','lock':'<rect x="4" y="10" width="16" height="12" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v3"/>','book':'<path d="M12 5c-3-2-6-2-10-2v16c4 0 7 0 10 2 3-2 6-2 10-2V3c-4 0-7 0-10 2Zm0 0v16"/>'}
def icon(name):return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+icons[name]+'</svg>'
def head(title,desc,path='/'):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{H(title)} · XailonHub by Infinia Labs</title><meta name="description" content="{H(desc)}"><link rel="canonical" href="{DOMAIN}{path}"><meta property="og:title" content="{H(title)} · XailonHub"><meta property="og:description" content="{H(desc)}"><meta property="og:image" content="{DOMAIN}/assets/help/home.jpg"><meta property="og:type" content="website"><meta name="theme-color" content="#f7f6f3"><link rel="icon" href="/assets/hub.svg" type="image/svg+xml"><link rel="preload" href="/assets/space-grotesk.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="nav"><div class="wrap"><a class="brand" href="https://infinialabs.ai" aria-label="Infinia Labs home"><img src="/assets/logo-labs.svg" alt="Infinia Technologies" width="139" height="24"><span class="labs">LABS</span></a><nav class="links" aria-label="Main navigation"><a href="/">XailonHub</a><a href="/#how-it-works">How it works</a><a href="/help/">Help & guides</a><a class="btn blue small nav-download" href="/#download">Get the app <span aria-hidden="true">↗</span></a></nav></div></header>'''
def foot():return f'''<footer class="footer"><div class="wrap"><div class="footer-top"><div><a class="brand" href="https://infinialabs.ai"><img class="brand-img" src="/assets/logo-labs-light.svg" alt="Infinia Technologies" width="158" height="27"><span class="labs">LABS</span></a><p>The R&amp;D division of Infinia Technologies.<br>AI tools that run on infrastructure you control.</p></div><div class="footer-links"><div><h3>XAILONHUB</h3><a href="/#download">Downloads</a><a href="/help/">User guide</a><a href="/help/install/">Installation</a></div><div><h3>RESOURCES</h3><a href="{REPO}/releases">Release notes</a><a href="{REPO}/issues">Report an issue</a><a href="/security/">Security & privacy</a></div><div><h3>INFINIA</h3><a href="https://infinialabs.ai">Infinia Labs</a><a href="https://infiniatechnologies.com">Infinia Technologies</a></div></div></div><div class="footer-bottom"><span>© 2026 Infinia Technologies</span><span>XailonHub · Powered by Infinia</span></div></div></footer></body></html>'''
def write(path,body,title,desc):
 p=SITE/path.lstrip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(head(title,desc,path)+body+foot())
def download_cards(os):
 result=''
 for a in release['desktop']:
  if a['os']!=os:continue
  if a.get('available'):
   action=f'<a class="btn blue" href="{H(a["url"])}">Download {H(a["format"])} <span class="arrow" aria-hidden="true">↓</span></a>'
   meta=f'{a.get("size_label","")} · {a["filename"]}'
  else:action='<span class="pending">Build in progress</span>';meta='The download will appear after packaging and verification.'
  result+=f'<article class="download-card"><h3>{H(a["label"])}</h3><p>{H(a["description"])}</p>{action}<span class="download-meta">{H(meta)}</span></article>'
 return result
panels=''.join(f'<section id="panel-{os}" role="tabpanel" aria-labelledby="tab-{os}" {"hidden" if os!="macos" else ""}><div class="downloads-grid">{download_cards(os)}</div></section>' for os in ['macos','windows','linux'])
body=f'''<main id="main"><section class="hero"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow">XailonHub · Your own AI network</span><h1>Your computers.<br>Your AI.<br><em>Better together.</em></h1><p>Bring your Mac, PC and local AI apps into one simple workspace. Share models, see what’s connected, and get things done—on your own devices.</p><div class="actions"><a class="btn blue" href="#download">Get XailonHub <span class="arrow" aria-hidden="true">↓</span></a><a class="btn outline" href="/help/">Take a quick tour <span aria-hidden="true">↗</span></a></div><p class="subline">A lightweight desktop app. No browser required.</p></div><div class="hero-scene"><div class="float-note"><span class="pulse" aria-hidden="true"></span>One workspace. Every connected device.</div><div class="window"><div class="bar"><i></i><i></i><i></i><span>XailonHub — Home</span></div><img src="/assets/help/home.jpg" alt="XailonHub dashboard showing an interactive map of connected computers and AI models" width="1320" height="880" fetchpriority="high"></div><div class="device-chip">{icon('hub')}<div>Work across your devices<small>Mac · Windows · Linux</small></div></div><span class="scene-label">Illustrative workspace</span></div></div><div class="support"><span>Built for the computers you already use</span><div class="support-list"><span>{icon('mac')} macOS</span><span>{icon('windows')} Windows</span><span>{icon('linux')} Linux</span></div><span>Local first. Cloud optional.</span></div></div></section>
<section class="section how" id="how-it-works"><div class="wrap"><div class="intro-row"><div><span class="eyebrow">A few minutes to connected</span><h2>A shared workspace.<br>A surprisingly simple setup.</h2></div><p>You don’t need to know which port goes where. Start with one computer, then bring the others along.</p></div><div class="how-grid"><article><span class="step-no">01 / MAKE YOURSELF AT HOME</span><h3>Open your Hub.</h3><p>Install the app and follow the welcome guide. Give your computer a name and choose a personal or shared workspace.</p><a class="text-link" href="/help/first-setup/">Set up your first Hub <span>↗</span></a></article><article><span class="step-no">02 / BRING YOUR DEVICES</span><h3>Connect with a code.</h3><p>Open XailonHub on another computer. A short pairing code brings it into the same workspace—no account required for local use.</p><a class="text-link" href="/help/connect-device/">Connect a computer <span>↗</span></a></article><article><span class="step-no">03 / PUT YOUR AI TO WORK</span><h3>Pick a model. Start talking.</h3><p>Connect an AI engine you already run. Use its models from any paired computer, with a clear view of where each request goes.</p><a class="text-link" href="/help/add-engine/">Connect an AI engine <span>↗</span></a></article></div><div class="flow"><svg class="flow-lines" viewBox="0 0 700 200" preserveAspectRatio="none" aria-hidden="true"><path d="M0 65H700"/><path d="M700 80H0"/></svg><div class="flow-node"><div class="orb">{icon('laptop')}</div><strong>Your everyday computer</strong><small>Ask, create and work</small></div><div class="flow-node"><div class="orb center">{icon('hub')}</div><strong>XailonHub</strong><small>Connect and route</small></div><div class="flow-node"><div class="orb">{icon('linux')}</div><strong>Your AI computer</strong><small>Run and share models</small></div></div><p class="flow-caption">One computer can do all three. Add more whenever you’re ready.</p></div></section>
<section class="section"><div class="wrap"><div class="intro-row"><div><span class="eyebrow">Less setup. More clarity.</span><h2>See your AI working together.</h2></div><p>A visual workspace for people, with the controls you need when you need them.</p></div><div class="feature-grid"><article class="feature"><div class="feature-copy"><h3>Know what’s connected.</h3><p>Explore your devices, their hardware and their health. Follow the live network map to see where work happens.</p></div><img src="/assets/help/devices.jpg" alt="My devices screen with hardware details and connection status" width="1320" height="880" loading="lazy"></article><article class="feature soft"><div class="feature-copy"><h3>Help is part of the app.</h3><p>Step-by-step guides, real interface screenshots and practical answers. Available even when you’re offline.</p><a class="text-link" href="/help/">Explore the user guide <span>↗</span></a></div><img src="/assets/help/setup.jpg" alt="The XailonHub welcome wizard with guided setup choices" width="1320" height="880" loading="lazy"></article></div></div></section>
<section class="section download" id="download"><div class="wrap"><span class="eyebrow">Make it your workspace</span><div class="download-head"><h2>Get XailonHub.</h2><span class="version">v{H(release['version'])} · Public preview</span></div><p class="status-text">Choose your operating system and processor. The app includes the Hub, interface and illustrated help; AI engines and models are installed separately.</p><div class="platform-tabs" role="tablist" aria-label="Operating system"><button id="tab-macos" role="tab" aria-selected="true" aria-controls="panel-macos" data-platform="macos">{icon('mac')}macOS</button><button id="tab-windows" role="tab" aria-selected="false" aria-controls="panel-windows" data-platform="windows" tabindex="-1">{icon('windows')}Windows</button><button id="tab-linux" role="tab" aria-selected="false" aria-controls="panel-linux" data-platform="linux" tabindex="-1">{icon('linux')}Linux</button></div>{panels}<div class="notice"><strong>Before you install:</strong> these are public-preview builds. macOS packages are ad-hoc signed, not Apple-notarized; Windows packages are not publisher-signed. Your OS may show a security warning. <a href="/help/install/">Read the installation and verification guide.</a></div><div class="download-foot"><a href="{REPO}/releases/tag/v{H(release['version'])}">All downloads & release notes ↗</a><a href="{REPO}/releases/download/v{H(release['version'])}/checksums.txt">SHA-256 checksums ↗</a><a href="/help/install/">Which processor do I have? ↗</a></div><details class="cli-box"><summary>Running a server or prefer the command line?</summary><p>The CLI edition runs the same Hub with a browser dashboard. This command installs the CLI, not the desktop app.</p><div class="code-row"><code id="install-command">curl -fsSL https://xailonhub.infinialabs.ai/install.sh | sh</code><button type="button" data-copy="install-command" aria-label="Copy CLI installation command">Copy</button></div><p>On Windows, use the PowerShell installer in the <a class="text-link" href="/help/install/#cli">installation guide ↗</a>. Inspect scripts before running them.</p></details></div></section>
<section class="section"><div class="wrap"><div class="intro-row"><div><span class="eyebrow">Your workspace. Your choices.</span><h2>Local first, by design.</h2></div></div><div class="trust-grid"><article>{icon('lock')}<h3>Private administration.</h3><p>The desktop app uses its own authenticated local session. The normal API port exposes inference, not the admin console.</p></article><article>{icon('shield')}<h3>Connected, with boundaries.</h3><p>Paired computers communicate over encrypted connections. Cloud routing and relay connections are optional and off for new setups.</p></article><article>{icon('book')}<h3>Clear, inspectable releases.</h3><p>Downloads, checksums, release notes and security information live in a public repository. Know what you’re installing.</p></article></div><div class="help-banner"><div><h2>A little guidance goes a long way.</h2><p>From your first Hub to a whole room of computers.</p></div><a class="btn" href="/help/">Open the user guide <span>↗</span></a></div></div></section></main>'''
# Resolve IDs from the guide rather than assuming a setup slug.
body=body.replace('/help/first-setup/','/help/'+guides['guides'][0]['id']+'/')
write('/',body,'Your computers. Your AI. Better together.','Connect your Mac, Windows and Linux computers in one lightweight AI workspace. Download XailonHub and follow the illustrated setup guide.')
cards=''.join(f'<a class="guide-card" data-guide data-search="{H(g["title"]+" "+g["summary"]+" "+g["category"])}" href="/help/{H(g["id"])}/"><small>{H(g["category"])} · {H(g["minutes"])} min</small><h2>{H(g["title"])}</h2><p>{H(g["summary"])}</p><span class="text-link">Read the guide ↗</span></a>' for g in guides['guides'])
faqs=''.join(f'<details><summary>{H(f.get("question",f.get("q","")))}</summary><p>{H(f.get("answer",f.get("a","")))}</p></details>' for f in guides.get('faqs',[]))
write('/help/',f'<main id="main"><div class="wrap"><section class="help-hero"><a class="crumb" href="/">XailonHub / Help</a><h1>A clear path to getting started.</h1><p>Step-by-step guides for your workspace. The same help is built into the app.</p><div class="actions"><a class="btn blue" href="/help/install/">Start with installation ↗</a></div><p class="status-text">&nbsp;</p><label for="guide-search" class="eyebrow">Find a guide</label><input id="guide-search" class="search" type="search" placeholder="Search setup, devices, models…" aria-describedby="search-status"><p id="search-status" class="status-text" aria-live="polite">{len(guides["guides"])} guides</p></section><div class="guide-grid">{cards}</div><p id="search-empty" class="empty" hidden>No matching guide. Try “devices”, “engine” or “privacy”.</p><section class="faq"><h2>Common questions.</h2>{faqs}</section></div></main>','Help & user guide','Step-by-step XailonHub guides with screenshots: installation, pairing, AI engines, privacy, assistants and troubleshooting.')
def nav(active):return '<nav class="guide-nav" aria-label="Help topics"><a href="/help/">← All guides</a><a href="/help/install/" '+('aria-current="page"' if active=='install' else '')+'>Install XailonHub</a>'+''.join(f'<a href="/help/{H(g["id"])}/" '+('aria-current="page"' if active==g['id'] else '')+f'>{H(g["title"])}</a>' for g in guides['guides'])+'</nav>'
def article(content,active):return f'<main id="main"><div class="wrap guide-layout">{nav(active)}<article class="article">{content}</article></div></main>'
for g in guides['guides']:
 steps=''.join(f'<li><h2>{H(s["title"])}</h2><p>{H(s["body"])}</p></li>' for s in g['steps'])
 content=f'<a class="crumb" href="/help/">Help / {H(g["category"])}</a><h1>{H(g["title"])}</h1><p class="lead">{H(g["summary"])}</p><div class="notice"><strong>Before you start</strong><p>{H(g["before"])}</p></div><figure><img src="/assets/help/{H(g["image"])}.jpg" alt="{H(g["caption"])}" width="1320" height="880"><figcaption>{H(g["caption"])}</figcaption></figure><ol>{steps}</ol><h2>You’re done when…</h2><p>{H(g["success"])}</p><div class="notice">{H(g["note"])}</div><p><a href="/help/">← Back to all guides</a></p>'
 write('/help/'+g['id']+'/',article(content,g['id']),g['title'],g['summary'])
install='''<a class="crumb" href="/help/">Help / Installation</a><h1>Install your new workspace.</h1><p class="lead">Choose your computer, check the download, and open XailonHub. You don’t need Go, Rust or Node.js to run the app.</p><div class="notice"><strong>Public preview</strong><p>These builds are not Apple-notarized or Windows publisher-signed. Download only from this portal or our linked GitHub release repository. Checksums detect corruption; they are not a publisher signature.</p></div><h2>1. Choose the right download</h2><h3>macOS</h3><p>Open Apple menu → About This Mac. If you see “Chip” with an Apple M-series name, choose Apple Silicon. If you see an Intel processor, choose Intel. macOS 12 or later is required.</p><p>Open the DMG and drag XailonHub into Applications. Open it from Applications. If Gatekeeper blocks this preview, review the warning and source in System Settings → Privacy &amp; Security. Only use the app-specific “Open Anyway” option if you trust this build. Do not disable Gatekeeper globally.</p><h3>Windows</h3><p>Open Settings → System → About → System type. Snapdragon computers normally use ARM64; Intel and AMD computers normally use x64. Download the matching setup.exe and follow the per-user installer. The installer includes the offline Microsoft WebView2 runtime needed by the app.</p><p>Windows may show an unknown-publisher or SmartScreen warning because this preview is not publisher-signed. Check the source and checksum before deciding whether to proceed. Managed devices may require your administrator’s approval.</p><h3>Linux</h3><p>Use the .deb package on Ubuntu 24.04+ or a compatible Debian-based system. ARM64 covers aarch64 machines; x64 covers amd64 machines. Check your processor with <code>uname -m</code>. Install with <code>sudo apt install ./XailonHub_0.3.3_linux_arm64.deb</code>, substituting your downloaded filename. The package manager installs the required WebKitGTK system libraries.</p><p>RPM packages are also provided for compatible distributions with WebKitGTK 4.1 and GTK 3. Install the downloaded RPM through your package manager. Distribution-specific runtime testing is still limited.</p><h2>2. Verify your download</h2><p>Compare its SHA-256 value with <a href="https://github.com/infinialabs-ai/xailon-hub-releases/releases/download/v0.3.3/checksums.txt">checksums.txt from the same release</a>. On macOS run <code>shasum -a 256 &lt;downloaded-file&gt;</code>; on Linux use <code>sha256sum &lt;downloaded-file&gt;</code>; on Windows PowerShell use <code>Get-FileHash &lt;downloaded-file&gt; -Algorithm SHA256</code>. Do not install if the values differ.</p><h2>3. Open the app and finish setup</h2><ol><li><h2>Allow local networking when asked</h2><p>XailonHub needs local-network access to discover and connect your computers. On macOS, check System Settings → Privacy &amp; Security → Local Network. On Windows, allow the Hub on your trusted private network when Windows Firewall asks. You do not need to expose it to the public internet.</p></li><li><h2>Choose a workspace</h2><p>Follow the welcome screens to create a Hub or join an existing one. You can start with one computer and add others later.</p></li><li><h2>Connect an AI engine</h2><p>The app includes the Hub and interface. AI engines and model weights are separate. Add an engine you already run, or pair a computer that has one.</p></li></ol><h2>Where is the admin console?</h2><p>Open <strong>Settings inside XailonHub</strong>. On macOS, you can also press ⌘,. The desktop edition intentionally does not expose its admin console at localhost:4747; that address serves the inference API only.</p><h2>Already running the command-line Hub?</h2><p>Stop the existing instance before opening the desktop app, or its ports may already be in use. To preserve pairing, back up and move its complete state directory with the configuration. Update <code>node.data_dir</code> to the new location. Do not run two copies with the same identity.</p><h2>Where does the app store data?</h2><p>macOS: <code>~/Library/Application Support/ai.infinialabs.xailonhub.desktop/</code><br>Windows: <code>%LOCALAPPDATA%\\ai.infinialabs.xailonhub.desktop\\</code><br>Linux: <code>~/.local/share/ai.infinialabs.xailonhub.desktop/</code> (or your configured XDG data location).</p><p>The folder contains configuration, pairing state and local logs. Keep backups private. Removing the app does not remove this data. Closing the app stops its Hub; independently running AI engines stay running.</p><h2 id="cli">Command-line and server installation</h2><p>The CLI edition uses a browser dashboard and can run as a background service. These commands install the CLI, not the desktop app. Read the scripts before running them.</p><h3>macOS and Linux</h3><pre><code>curl -fsSL https://xailonhub.infinialabs.ai/install.sh | sh</code></pre><h3>Windows PowerShell</h3><pre><code>irm https://xailonhub.infinialabs.ai/install.ps1 | iex</code></pre><p>For a server, use the shell installer with <code>sh -s -- --hub</code>, or the PowerShell installer with <code>-Hub</code>. For installation without a background service, use <code>--no-service</code> or <code>-NoStartup</code>. The installers verify release checksums.</p>'''
write('/help/install/',article(install,'install'),'Install XailonHub','Download the right XailonHub installer for macOS, Windows or Linux. Verify checksums, complete setup and find your app data.')
security='''<a class="crumb" href="/">XailonHub / Trust</a><h1>Clear boundaries.<br>Informed choices.</h1><p class="lead">XailonHub connects your AI tools and devices. These are the protections built in—and the choices that remain yours.</p><h2>Local administration stays private</h2><p>The desktop window connects to a random loopback port protected by an ephemeral HttpOnly session cookie. A one-use launch ticket travels through a private process pipe. The regular inference listener does not expose administration routes in desktop mode.</p><h2>A limited native interface</h2><p>The web interface has no granted native shell or filesystem commands. External navigation, popups, downloads and developer tools are disabled. The bundled backend is verified before launch. This is not an operating-system sandbox: configured agents and AI engines retain their own access and permissions.</p><h2>Your network and routing policy</h2><p>Paired Hubs use authenticated encrypted peer connections. Cloud and relay are off in new configurations. Enabling cloud routing changes where requests may go; review the privacy controls before using sensitive information. Local inference authentication follows your gateway settings.</p><h2>Portal privacy</h2><p>This portal uses no analytics scripts, advertising cookies or login. Fonts, illustrations and help are served from this site. Cloudflare processes normal web requests to deliver it, and GitHub handles release downloads. Neither service receives your AI prompts through this portal.</p><h2>Release status</h2><p>The first desktop release is a public preview. macOS builds are ad-hoc signed, not notarized. Windows builds are unsigned. Linux uses the system WebKitGTK runtime. Keep your OS and webview up to date. Checksums verify file integrity; they do not replace a trusted publisher signature.</p><h2>Linux dependency review</h2><p>The GLib 0.18.5 iterator fix from upstream PR #1343 is backported for RUSTSEC-2024-0429. Some Linux transitive dependencies have unmaintained-package notices; these are tracked in the release security notes. Public packages include third-party notices and the patched library source.</p><h2>Report a security issue</h2><p>Please report vulnerabilities privately to <a href="mailto:hello@infinialabs.ai">hello@infinialabs.ai</a> with the subject “XailonHub security”. Avoid including credentials or private prompts in public issues.</p>'''
write('/security/',article(security,''),'Security & privacy','How XailonHub protects local administration, connects devices and packages its public-preview releases.')
(SITE/'404.html').write_text(head('Page not found','Find your way back to XailonHub.')+'<main id="main" class="wrap section"><span class="eyebrow">404</span><h1>Let’s get you back home.</h1><p class="actions"><a class="btn blue" href="/">Open XailonHub home</a><a class="btn outline" href="/help/">Browse the guide</a></p></main>'+foot())
(SITE/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+DOMAIN+'/sitemap.xml\n')
urls=['/','/help/','/help/install/','/security/']+['/help/'+g['id']+'/' for g in guides['guides']]
(SITE/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+DOMAIN+u+'</loc></url>' for u in urls)+'</urlset>')
(SITE/'release.json').write_text(json.dumps(release,indent=2)+'\n')
print('Built portal and',len(urls)-1,'help/security pages.')
